const makeInviteCode=(role:'manager'|'tenant',orgs:Org[])=>{let code:string;do{const bytes=crypto.getRandomValues(new Uint8Array(5));const suffix=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('').toUpperCase();code=`NT-${role==='manager'?'MGR':'TEN'}-${suffix}`}while(orgs.some(org=>org.inviteManager===code||org.inviteTenant===code));return code};
const readImageAsDataUrl=(file:File)=>new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>typeof reader.result==='string'?resolve(reader.result):reject(new Error('Could not read the selected image'));reader.onerror=()=>reject(reader.error||new Error('Could not read the selected image'));reader.readAsDataURL(file)});
